import { createRequire } from "node:module";
import { writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const { roles } = require("../src/data/roles.js");
const roleLimits = Object.fromEntries(roles.map((role) => [role.id, role.maxCount]));
if (roles.length !== 98 || new Set(roles.map((role) => role.id)).size !== roles.length) {
  throw new Error("Expected 98 unique base and advanced role entries.");
}
const output = [
  "// Generated by scripts/generate-role-limits.mjs from src/data/roles.js.",
  "export const ROLE_LIMITS: Record<string, number> = " + JSON.stringify(roleLimits, null, 2) + ";",
  "export const VALID_ROLE_IDS = Object.keys(ROLE_LIMITS);",
  ""
].join("\n");
const target = resolve(dirname(fileURLToPath(import.meta.url)), "../supabase/functions/two-rooms-identity-game/role-limits.ts");
await writeFile(target, output, "utf8");
console.log("Generated server allowlist for " + roles.length + " roles.");
